19:     struct Plot {
20:         uint256 podIndex;
21:         uint256 podAmounts;
22:     }
23:     struct MigratedPlotData {
24:         address account;
25:         Plot[] plots;
26:     }
27: 
28:     // emitted when a plot is migrated.
29:     event MigratedPlot(address indexed account, uint256 indexed plotIndex, uint256 pods);
30: 
31:     /**
32:      * @notice Re-initializes the field.
33:      * @param accountPlots the plots for each account
34:      * @param totalPods The total number of pods on L1.
35:      * @param harvestable The number of harvestable pods on L1.
36:      * @param harvested The number of harvested pods on L1.
37:      * @param initialTemperature the initial Temperature of the field.
38:      */
39:     function init(
40:         MigratedPlotData[] calldata accountPlots,
41:         uint256 totalPods,
42:         uint256 harvestable,
43:         uint256 harvested,
44:         uint256 fieldId,
45:         uint8 initialTemperature
46:     ) external {
47:         uint256 calculatedTotalPods;
48:         for (uint i; i < accountPlots.length; i++) {
49:             for (uint j; j < accountPlots[i].plots.length; i++) {
50:                 uint256 podIndex = accountPlots[i].plots[j].podIndex;
51:                 uint256 podAmount = accountPlots[i].plots[j].podAmounts;
52:                 s.accts[accountPlots[i].account].fields[fieldId].plots[podIndex] = podAmount;
53:                 s.accts[accountPlots[i].account].fields[fieldId].plotIndexes.push(podIndex);
54:                 emit MigratedPlot(accountPlots[i].account, podIndex, podAmount);
55:                 calculatedTotalPods += podAmount;
56:             }
57:         }
58: 
59:         //  perform verfication:
60:         require(calculatedTotalPods == totalPods, "ReseedField: totalPods mismatch");
61:         require(totalPods >= harvestable, "ReseedField: harvestable mismatch");
62:         require(harvestable >= harvested, "ReseedField: harvested mismatch");
63: 
64:         s.sys.field.pods = totalPods;
65:         s.sys.field.harvestable = harvestable;
66:         s.sys.field.harvested = harvested;
67: 
68:         // soil demand initialization.
69:         s.sys.weather.thisSowTime = type(uint32).max;
70:         s.sys.weather.lastSowTime = type(uint32).max;
71:         s.sys.weather.temp = initialTemperature;
72:     }
73: }
